```typescript
// ==================== 类型定义 ====================

interface Item {
  type: ItemType;
  value: number;
  weight: number;
  id?: string;
}

interface Card {
  type: CardType;
  multiplier: number;
  duration: number;
  id?: string;
}

interface ActiveBuff {
  type: string;
  multiplier: number;
  remainingTime: number;
}

enum ItemType {
  GOLD_SMALL = 'GOLD_SMALL',
  GOLD_MEDIUM = 'GOLD_MEDIUM',
  GOLD_LARGE = 'GOLD_LARGE',
  DIAMOND = 'DIAMOND',
  ROCK = 'ROCK',
  BOMB = 'BOMB',
  TREASURE = 'TREASURE'
}

enum CardType {
  SPEED = 'speed',
  VALUE = 'value',
  STRENGTH = 'strength',
  TIME = 'time',
  LUCK = 'luck'
}

enum GameState {
  IDLE = 'IDLE',
  PLAYING = 'PLAYING',
  PAUSED = 'PAUSED',
  GAME_OVER = 'GAME_OVER'
}

// ==================== 修复后的类 ====================

class GoldMiner {
  private gold: number = 0;
  private timeLeft: number = 60;
  private hookSpeed: number = 5;
  private baseHookSpeed: number = 5;
  private gameState: GameState = GameState.IDLE;
  private isHookFiring: boolean = false;
  private hookPosition: { x: number; y: number } = { x: 0, y: 0 };

  // 增益效果系统
  private activeBuffs: ActiveBuff[] = [];
  private valueMultiplier: number = 1;
  private strengthMultiplier: number = 1;

  // 连击系统
  private comboCount: number = 0;
  private lastCollectTime: number = 0;

  // 关卡系数
  private difficultyMultiplier: number = 1;

  // ==================== 收集物品（修复Bug 1,2,3,4）====================

  collectItem(item: Item | null | undefined): void {
    // Bug 1修复: 验证item是否存在
    if (!item) {
      console.warn('collectItem: item is null or undefined');
      return;
    }

    // Bug 2修复: 验证value是否有效
    if (typeof item.value !== 'number' || isNaN(item.value) || item.value < 0) {
      console.warn(`collectItem: invalid value ${item.value}`);
      return;
    }

    // Bug 4修复: 处理特殊物品类型
    if (item.type === ItemType.BOMB) {
      this.handleBomb();
      return;
    }

    if (item.type === ItemType.ROCK) {
      // 石头价值低，但有重量
      const rockValue = Math.max(0, item.value * 0.1);
      this.gold += rockValue * this.valueMultiplier;
    } else {
      // 正常物品，应用价值增益
      this.gold += item.value * this.valueMultiplier;
    }

    // Bug 3修复: 重量影响收回速度（需要在收回逻辑中应用）
    // 这里记录重量，供后续使用
    this.adjustRetractSpeed(item.weight);

    // 更新连击
    this.updateCombo();

    console.log(`Collected ${item.type}! Value: ${item.value}, Total: ${this.gold}`);
  }

  // 处理炸弹
  private handleBomb(): void {
    console.log('BOOM! Bomb collected, losing gold!');
    this.gold = Math.max(0, this.gold - 50);
    this.comboCount = 0; // 重置连击
  }

  // 调整收回速度（根据重量）
  private adjustRetractSpeed(weight: number): void {
    // 重量越大，速度越慢
    const speedPenalty = Math.max(0.3, 1 - weight / 200);
    this.hookSpeed = this.baseHookSpeed * speedPenalty * this.strengthMultiplier;
  }

  // ==================== 更新时间（修复Bug 5,6）====================

  updateTime(deltaTime: number): void {
    if (this.gameState !== GameState.PLAYING) {
      return;
    }

    if (typeof deltaTime !== 'number' || deltaTime < 0) {
      console.warn('updateTime: invalid deltaTime');
      return;
    }

    this.timeLeft -= deltaTime;

    // Bug 5修复: 处理时间耗尽
    if (this.timeLeft <= 0) {
      this.timeLeft = 0;
      // Bug 6修复: 结束游戏
      this.endGame();
      return;
    }

    // 更新增益效果持续时间
    this.updateBuffs(deltaTime);

    console.log(`Time left: ${this.timeLeft.toFixed(1)}`);
  }

  private endGame(): void {
    this.gameState = GameState.GAME_OVER;
    const finalScore = this.calculateScore();
    console.log(`Game Over! Final Score: ${finalScore}`);
  }

  // ==================== 发射钩子（修复Bug 7,8,9,10）====================

  fireHook(angle: number): void {
    // Bug 8修复: 检查是否已经在发射
    if (this.isHookFiring) {
      console.warn('fireHook: hook is already firing');
      return;
    }

    // Bug 7修复: 验证角度范围
    // 角度应该以度为单位，转换为弧度
    let normalizedAngle = angle;
    if (typeof angle !== 'number' || isNaN(angle)) {
      console.warn('fireHook: invalid angle, using default');
      normalizedAngle = 0;
    }

    // 转换为0-360范围
    normalizedAngle = ((normalizedAngle % 360) + 360) % 360;

    // Bug 10修复: 明确角度单位转换
    // 假设输入是角度，转换为弧度
    const radians = (normalizedAngle * Math.PI) / 180;

    // Bug 9修复: 重置钩子位置
    this.hookPosition = { x: 0, y: 0 };

    const velocityX = Math.cos(radians) * this.hookSpeed;
    const velocityY = Math.sin(radians) * this.hookSpeed;

    this.isHookFiring = true;

    console.log(`Hook fired at ${normalizedAngle.toFixed(1)}° (radians: ${radians.toFixed(3)})`);
  }

  // 钩子收回时重置状态
  onHookRetracted(): void {
    this.isHookFiring = false;
    this.hookSpeed = this.baseHookSpeed; // 恢复基础速度
  }

  // ==================== 碰撞检测（修复Bug 11,12）====================

  checkCollision(
    hookX: number,
    hookY: number,
    itemX: number,
    itemY: number,
    itemRadius: number
  ): boolean {
    // 验证参数
    if ([hookX, hookY, itemX, itemY, itemRadius].some(
      v => typeof v !== 'number' || isNaN(v)
    )) {
      console.warn('checkCollision: invalid parameters');
      return false;
    }

    // Bug 11修复: 使用平方距离比较，避免开方运算
    const dx = hookX - itemX;
    const dy = hookY - itemY;
    const distanceSquared = dx * dx + dy * dy;
    const radiusSquared = itemRadius * itemRadius;

    // Bug 12修复: 处理可能的NaN（已通过上面的验证避免）
    return distanceSquared <= radiusSquared;
  }

  // ==================== 应用增益卡（修复Bug 13,14,15,16,17）====================

  applyCard(card: Card | null | undefined): void {
    // Bug 13修复: 验证card是否存在
    if (!card) {
      console.warn('applyCard: card is null or undefined');
      return;
    }

    // Bug 14修复: 验证multiplier合法性
    if (typeof card.multiplier !== 'number' || 
        isNaN(card.multiplier) || 
        card.multiplier <= 0 || 
        card.multiplier > 10) {
      console.warn(`applyCard: invalid multiplier ${card.multiplier}`);
      return;
    }

    // Bug 15修复: 实现持续时间逻辑
    const buff: ActiveBuff = {
      type: card.type,
      multiplier: card.multiplier,
      remainingTime: card.duration
    };

    // Bug 17修复: 使用switch处理不同卡牌类型
    switch (card.type) {
      case CardType.SPEED:
        this.hookSpeed = this.baseHookSpeed * card.multiplier;
        this.activeBuffs.push(buff);
        console.log(`Speed boost: ${card.multiplier}x for ${card.duration}s`);
        break;

      case CardType.VALUE:
        // Bug 16修复: 存储价值增益
        this.valueMultiplier = card.multiplier;
        this.activeBuffs.push(buff);
        console.log(`Value boost: ${card.multiplier}x for ${card.duration}s`);
        break;

      case CardType.STRENGTH:
        this.strengthMultiplier = card.multiplier;
        this.activeBuffs.push(buff);
        console.log(`Strength boost: ${card.multiplier}x for ${card.duration}s`);
        break;

      case CardType.TIME:
        this.timeLeft += card.duration;
        console.log(`Time added: ${card.duration}s`);
        break;

      default:
        console.warn(`applyCard: unknown card type ${card.type}`);
    }
  }

  // 更新增益效果
  private updateBuffs(deltaTime: number): void {
    this.activeBuffs = this.activeBuffs.filter(buff => {
      buff.remainingTime -= deltaTime;

      if (buff.remainingTime <= 0) {
        // 增益结束，恢复原值
        this.removeBuff(buff);
        return false;
      }

      return true;
    });
  }

  // 移除增益效果
  private removeBuff(buff: ActiveBuff): void {
    switch (buff.type) {
      case CardType.SPEED:
        this.hookSpeed = this.baseHookSpeed;
        break;
      case CardType.VALUE:
        this.valueMultiplier = 1;
        break;
      case CardType.STRENGTH:
        this.strengthMultiplier = 1;
        break;
    }
  }

  // ==================== 计算得分（修复Bug 18,19）====================

  calculateScore(): number {
    let score = this.gold;

    // Bug 18修复: 连击加成
    if (this.comboCount > 1) {
      const comboBonus = Math.min(this.comboCount * 0.1, 2.0); // 最多200%
      score *= (1 + comboBonus);
    }

    // Bug 19修复: 关卡难度系数
    score *= this.difficultyMultiplier;

    return Math.floor(score);
  }

  // 更新连击
  private updateCombo(): void {
    const now = Date.now();
    const comboWindow = 3000; // 3秒内收集算连击

    if (now - this.lastCollectTime < comboWindow) {
      this.comboCount++;
    } else {
      this.comboCount = 1;
    }

    this.lastCollectTime = now;
  }

  // ==================== 公共接口 ====================

  startGame(): void {
    this.gameState = GameState.PLAYING;
    this.gold = 0;
    this.timeLeft = 60;
    this.comboCount = 0;
    this.activeBuffs = [];
    this.isHookFiring = false;
    this.valueMultiplier = 1;
    this.strengthMultiplier = 1;
    this.hookSpeed = this.baseHookSpeed;
  }

  pauseGame(): void {
    if (this.gameState === GameState.PLAYING) {
      this.gameState = GameState.PAUSED;
    }
  }

  resumeGame(): void {
    if (this.gameState === GameState.PAUSED) {
      this.gameState = GameState.PLAYING;
    }
  }

  getGold(): number {
    return this.gold;
  }

  getTimeLeft(): number {
    return this.timeLeft;
  }

  getGameState(): GameState {
    return this.gameState;
  }

  getComboCount(): number {
    return this.comboCount;
  }
}
